public void placeOrder(Order order) {
    orderRepository.save(order);
    paymentClient.charge(order);           // HTTP call: can be slow, can fail
    inventoryClient.reserve(order);        // another HTTP call
    emailClient.sendConfirmation(order);   // and another
    analyticsClient.recordSale(order);
    searchClient.updatePopularity(order);
}
